/**
 * Server-side SFTP proxy for the in-portal file manager.
 *
 * This is a plain (non-"use server") module so it can be imported by both the
 * server actions (lib/actions-files.ts) and the upload/download route handler.
 * It never runs in the browser — the customer's root credentials stay on the
 * server; the browser only ever talks to our own actions/route.
 *
 * Connection target is derived EXACTLY like the server detail page:
 *   - dedicated-IP servers connect to their own IP on port 22
 *   - NAT servers use PUBLIC_IP + the forwarded SSH port
 * Username is always "root"; password is `server.rootPassword`.
 *
 * SANDBOX: on staging (NXEON_SANDBOX=1) no real SSH connection is ever opened —
 * every op is backed by a small in-memory simulated filesystem so the whole
 * file-manager UX works end to end without a live VM.
 */
import SftpClient from "ssh2-sftp-client";
import { SANDBOX } from "./sandbox";
import { decryptSecret } from "./crypto-box";

/**
 * Resolve a server's plaintext root password, preferring the encrypted-at-rest
 * value and falling back to the legacy plaintext column for rows that predate
 * encryption. Every READ of a root password must go through this helper so both
 * shapes keep working transparently.
 */
export function serverRootPassword(
  server: { rootPassword: string | null; rootPasswordEnc?: string | null }
): string | null {
  return decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
}

/** The minimal shape of a Server we need to open a connection. */
export type SftpServer = {
  id: string;
  rootPassword: string | null;
  rootPasswordEnc?: string | null;
  sshPort: number | null;
  dedicatedIp?: { address: string } | null;
};

export type SftpEntry = {
  name: string;
  /** "d" directory, "-" file, "l" symlink, etc. (ssh2-sftp-client `type`). */
  type: string;
  isDirectory: boolean;
  size: number;
  /** Unix mtime in ms. */
  modifiedMs: number;
  /** Numeric permission bits (e.g. 0o644), or null if unknown. */
  mode: number | null;
};

export type SftpStat = {
  isDirectory: boolean;
  size: number;
  modifiedMs: number;
  mode: number | null;
};

const CONNECT_TIMEOUT_MS = 10_000;

/** Max length for any absolute path we accept from the client. */
export const MAX_PATH_LEN = 4096;
/** Max length for a single path segment (file/folder name). */
export const MAX_NAME_LEN = 255;

/**
 * Normalize + validate an absolute POSIX path coming from the browser. Rejects
 * relative paths, `..` traversal, NUL bytes, and over-long paths. Returns a
 * cleaned absolute path (collapsed slashes, resolved `.`), always starting with
 * "/". Throws on anything suspicious — callers surface the message.
 */
export function normalizePath(input: string): string {
  if (typeof input !== "string") throw new Error("Invalid path.");
  if (input.length > MAX_PATH_LEN) throw new Error("Path is too long.");
  if (input.includes("\0")) throw new Error("Invalid path.");
  if (!input.startsWith("/")) throw new Error("Path must be absolute.");

  const out: string[] = [];
  for (const part of input.split("/")) {
    if (part === "" || part === ".") continue;
    if (part === "..") throw new Error("Path traversal is not allowed.");
    if (part.length > MAX_NAME_LEN) throw new Error("A path segment is too long.");
    out.push(part);
  }
  return "/" + out.join("/");
}

/**
 * Validate a single new file/folder name — no slashes, no traversal, no NUL,
 * not "." or "..". Returns the name unchanged if valid.
 */
export function validateName(name: string): string {
  if (typeof name !== "string" || name.length === 0) throw new Error("A name is required.");
  if (name.length > MAX_NAME_LEN) throw new Error("Name is too long.");
  if (name.includes("/") || name.includes("\0")) throw new Error("Name contains invalid characters.");
  if (name === "." || name === "..") throw new Error("That name is not allowed.");
  return name;
}

/** Join a validated absolute dir with a validated name, re-normalizing. */
export function joinPath(dir: string, name: string): string {
  return normalizePath(`${dir}/${name}`);
}

/**
 * Fixed directory every browser→server upload lands in. Uploads are ALWAYS
 * written here under a sanitized basename — never at a client-chosen path — so
 * a hostile filename can only ever create a file inside this one dir. Lives in
 * this plain module (not the "use server" action file) so it can be imported
 * and unit-tested without pulling in the server-action graph.
 */
export const UPLOAD_DIR = "/root/nxeon-uploads";

/**
 * Reduce an arbitrary, client-supplied filename to a SAFE basename that can only
 * land inside {@link UPLOAD_DIR}. Strips every directory component (POSIX `/`
 * and Windows `\`) so `../../etc/passwd` or `C:\evil\x` collapse to their final
 * segment, then runs the survivor through the same `validateName` the file
 * manager uses (rejects `/`, NUL, `.`, `..`, over-long names). Pure so the guard
 * can be unit-tested in isolation from any SFTP connection.
 */
export function sanitizeUploadName(raw: string): string {
  if (typeof raw !== "string") throw new Error("A name is required.");
  const base = raw.split(/[/\\]/).pop() ?? "";
  const trimmed = base.trim();
  if (!trimmed) throw new Error("A name is required.");
  return validateName(trimmed);
}

/**
 * Resolve the {host, port} for a server, mirroring the server detail page:
 * dedicated IP -> :22, otherwise PUBLIC_IP:sshPort.
 */
export function connectionTarget(server: SftpServer): { host: string; port: number } | null {
  const dedicated = !!server.dedicatedIp;
  const host = dedicated ? server.dedicatedIp!.address : process.env.PUBLIC_IP || "";
  const port = dedicated ? 22 : server.sshPort;
  if (!host || !port) return null;
  return { host, port };
}

/**
 * Open an SFTP connection, run `fn(client)`, and ALWAYS close it (finally).
 * In SANDBOX mode this is bypassed entirely — callers below short-circuit to
 * the in-memory filesystem before ever reaching here.
 */
export async function withSftp<T>(
  server: SftpServer,
  fn: (client: SftpClient) => Promise<T>
): Promise<T> {
  if (SANDBOX) {
    throw new Error("withSftp must not be called in sandbox mode");
  }
  const target = connectionTarget(server);
  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
  const password = serverRootPassword(server);
  if (!password) throw new Error("Server has no root password set.");

  const client = new SftpClient();
  try {
    await client.connect({
      host: target.host,
      port: target.port,
      username: "root",
      password,
      readyTimeout: CONNECT_TIMEOUT_MS,
    });
    return await fn(client);
  } finally {
    try {
      await client.end();
    } catch {
      /* best-effort close */
    }
  }
}

// ----------------------------------------------------------------------------
// Sandbox in-memory filesystem
// ----------------------------------------------------------------------------

type SimNode =
  | { type: "dir"; mtime: number; mode: number; children: Record<string, SimNode> }
  | { type: "file"; mtime: number; mode: number; content: string };
type SimDir = Extract<SimNode, { type: "dir" }>;

/** One simulated filesystem per server id, lazily seeded. */
const globalForSim = globalThis as unknown as { __nxeonSftpSim?: Map<string, SimNode> };
const simStore: Map<string, SimNode> = globalForSim.__nxeonSftpSim ?? new Map();
globalForSim.__nxeonSftpSim = simStore;

function seedSim(): SimNode {
  const now = Date.now();
  const file = (content: string, mode = 0o644): SimNode => ({
    type: "file",
    mtime: now,
    mode,
    content,
  });
  const dir = (children: Record<string, SimNode>, mode = 0o755): SimNode => ({
    type: "dir",
    mtime: now,
    mode,
    children,
  });
  return dir({
    root: dir({
      "readme.txt": file(
        "Welcome to your VPS (sandbox).\n\nThis is a simulated filesystem shown on the staging\nenvironment — no real SSH connection is made.\n"
      ),
      ".bashrc": file("# ~/.bashrc\nexport PATH=$PATH:/usr/local/bin\n"),
      projects: dir({
        "app.js": file("console.log('hello from your server');\n"),
        "notes.md": file("# Notes\n\n- Edit me from the file manager.\n"),
      }),
    }),
    etc: dir({
      "hostname": file("nxeon-vps\n"),
      "os-release": file('PRETTY_NAME="Ubuntu 24.04 LTS"\n', 0o644),
    }),
    var: dir({
      log: dir({
        "syslog": file("Jan  1 00:00:00 nxeon-vps systemd[1]: Started sandbox.\n"),
      }),
      www: dir({
        html: dir({
          "index.html": file("<!doctype html><h1>It works</h1>\n"),
        }),
      }),
    }),
    tmp: dir({}),
  });
}

function simRoot(serverId: string): SimNode {
  let node = simStore.get(serverId);
  if (!node) {
    node = seedSim();
    simStore.set(serverId, node);
  }
  return node;
}

/** Convert an rwx rights triad ("rwx","r-x","r--") into an octal mode integer. */
function rightsToMode(rights: { user: string; group: string; other: string }): number | null {
  if (!rights) return null;
  const bits = (s: string): number =>
    (s.includes("r") ? 4 : 0) + (s.includes("w") ? 2 : 0) + (s.includes("x") ? 1 : 0);
  return (bits(rights.user) << 6) | (bits(rights.group) << 3) | bits(rights.other);
}

function splitPath(p: string): string[] {
  return p.split("/").filter((s) => s.length > 0);
}

function simResolve(serverId: string, p: string): SimNode | null {
  let node = simRoot(serverId);
  for (const part of splitPath(p)) {
    if (node.type !== "dir") return null;
    const next = node.children[part];
    if (!next) return null;
    node = next;
  }
  return node;
}

function simParent(serverId: string, p: string): { parent: SimDir; name: string } | null {
  const parts = splitPath(p);
  if (parts.length === 0) return null;
  const name = parts[parts.length - 1];
  const parentPath = "/" + parts.slice(0, -1).join("/");
  const parent = simResolve(serverId, parentPath);
  if (!parent || parent.type !== "dir") return null;
  return { parent, name };
}

// ----------------------------------------------------------------------------
// Typed operations (sandbox-aware)
// ----------------------------------------------------------------------------

export async function listDir(server: SftpServer, path: string): Promise<SftpEntry[]> {
  if (SANDBOX) {
    const node = simResolve(server.id, path);
    if (!node) throw new Error("No such directory.");
    if (node.type !== "dir") throw new Error("Not a directory.");
    return Object.entries(node.children)
      .map(([name, child]) => ({
        name,
        type: child.type === "dir" ? "d" : "-",
        isDirectory: child.type === "dir",
        size: child.type === "file" ? Buffer.byteLength(child.content) : 0,
        modifiedMs: child.mtime,
        mode: child.mode,
      }))
      .sort((a, b) =>
        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
      );
  }

  return withSftp(server, async (client) => {
    const list = await client.list(path);
    return list
      .map((e) => ({
        name: e.name,
        type: e.type,
        isDirectory: e.type === "d",
        size: e.size,
        modifiedMs: e.modifyTime,
        // ssh2-sftp-client's list() returns rwx `rights` strings, not a numeric
        // mode — derive the octal permission bits from them.
        mode: rightsToMode(e.rights),
      }))
      .sort((a, b) =>
        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
      );
  });
}

export async function statPath(server: SftpServer, path: string): Promise<SftpStat> {
  if (SANDBOX) {
    const node = simResolve(server.id, path);
    if (!node) throw new Error("No such file or directory.");
    return {
      isDirectory: node.type === "dir",
      size: node.type === "file" ? Buffer.byteLength(node.content) : 0,
      modifiedMs: node.mtime,
      mode: node.mode,
    };
  }

  return withSftp(server, async (client) => {
    const s = await client.stat(path);
    return {
      isDirectory: s.isDirectory,
      size: s.size,
      modifiedMs: s.modifyTime,
      mode: typeof s.mode === "number" ? s.mode & 0o777 : null,
    };
  });
}

/**
 * Read a text file, capped at `maxBytes`. Throws if the target is larger than
 * the cap so we never buffer an unbounded file into memory / the editor.
 */
export async function readFileText(
  server: SftpServer,
  path: string,
  maxBytes: number
): Promise<string> {
  if (SANDBOX) {
    const node = simResolve(server.id, path);
    if (!node) throw new Error("No such file.");
    if (node.type !== "file") throw new Error("Not a file.");
    if (Buffer.byteLength(node.content) > maxBytes) {
      throw new Error("File is too large to edit in the browser.");
    }
    return node.content;
  }

  return withSftp(server, async (client) => {
    const s = await client.stat(path);
    if (s.isDirectory) throw new Error("Not a file.");
    if (s.size > maxBytes) throw new Error("File is too large to edit in the browser.");
    const buf = (await client.get(path)) as Buffer;
    return buf.toString("utf8");
  });
}

export async function writeFileText(
  server: SftpServer,
  path: string,
  content: string
): Promise<void> {
  if (SANDBOX) {
    const loc = simParent(server.id, path);
    if (!loc) throw new Error("Invalid path.");
    const existing = loc.parent.children[loc.name];
    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
    loc.parent.children[loc.name] = {
      type: "file",
      mtime: Date.now(),
      mode: existing?.type === "file" ? existing.mode : 0o644,
      content,
    };
    return;
  }

  await withSftp(server, async (client) => {
    await client.put(Buffer.from(content, "utf8"), path);
  });
}

export async function mkdirPath(server: SftpServer, path: string): Promise<void> {
  if (SANDBOX) {
    const loc = simParent(server.id, path);
    if (!loc) throw new Error("Invalid path.");
    if (loc.parent.children[loc.name]) throw new Error("A file or folder with that name already exists.");
    loc.parent.children[loc.name] = { type: "dir", mtime: Date.now(), mode: 0o755, children: {} };
    return;
  }

  await withSftp(server, async (client) => {
    await client.mkdir(path, false);
  });
}

export async function renamePath(
  server: SftpServer,
  from: string,
  to: string
): Promise<void> {
  if (SANDBOX) {
    const src = simResolve(server.id, from);
    if (!src) throw new Error("No such file or directory.");
    const dst = simParent(server.id, to);
    if (!dst) throw new Error("Invalid destination.");
    if (dst.parent.children[dst.name]) {
      throw new Error("A file or folder with that name already exists.");
    }
    const srcLoc = simParent(server.id, from);
    if (!srcLoc) throw new Error("Cannot rename the root.");
    delete srcLoc.parent.children[srcLoc.name];
    dst.parent.children[dst.name] = { ...src, mtime: Date.now() };
    return;
  }

  await withSftp(server, async (client) => {
    await client.rename(from, to);
  });
}

/** Remove a file, or recursively remove a directory. */
export async function removePath(server: SftpServer, path: string): Promise<void> {
  if (SANDBOX) {
    const loc = simParent(server.id, path);
    if (!loc) throw new Error("Cannot remove the root.");
    if (!loc.parent.children[loc.name]) throw new Error("No such file or directory.");
    delete loc.parent.children[loc.name];
    return;
  }

  await withSftp(server, async (client) => {
    const s = await client.stat(path);
    if (s.isDirectory) {
      await client.rmdir(path, true); // recursive
    } else {
      await client.delete(path);
    }
  });
}

export async function chmodPath(server: SftpServer, path: string, mode: number): Promise<void> {
  if (SANDBOX) {
    const node = simResolve(server.id, path);
    if (!node) throw new Error("No such file or directory.");
    node.mode = mode & 0o777;
    return;
  }

  await withSftp(server, async (client) => {
    await client.chmod(path, mode & 0o777);
  });
}

// ----------------------------------------------------------------------------
// Streaming helpers for the upload/download route
// ----------------------------------------------------------------------------

/** Read an entire file into a Buffer (used by the download endpoint). */
export async function readFileBuffer(server: SftpServer, path: string): Promise<Buffer> {
  if (SANDBOX) {
    const node = simResolve(server.id, path);
    if (!node) throw new Error("No such file.");
    if (node.type !== "file") throw new Error("Not a file.");
    return Buffer.from(node.content, "utf8");
  }

  return withSftp(server, async (client) => {
    const s = await client.stat(path);
    if (s.isDirectory) throw new Error("Not a file.");
    return (await client.get(path)) as Buffer;
  });
}

/** Write a Buffer to a path (used by the upload endpoint). */
export async function writeFileBuffer(
  server: SftpServer,
  path: string,
  data: Buffer
): Promise<void> {
  if (SANDBOX) {
    const loc = simParent(server.id, path);
    if (!loc) throw new Error("Invalid path.");
    const existing = loc.parent.children[loc.name];
    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
    loc.parent.children[loc.name] = {
      type: "file",
      mtime: Date.now(),
      mode: existing?.type === "file" ? existing.mode : 0o644,
      content: data.toString("utf8"),
    };
    return;
  }

  await withSftp(server, async (client) => {
    await client.put(data, path);
  });
}

