// TEMP helper for sp-ideas re-integration. Runs a remote command on server .200.
// Never prints the plaintext password. Usage: node _sp_reintg_runner.cjs <b64script>
const fs = require("fs");
const path = require("path");
const { Client } = require("ssh2");
const { execSync } = require("child_process");

// Load .env (AUTH_SECRET, DATABASE_URL)
const envTxt = fs.readFileSync(path.join(__dirname, ".env"), "utf8");
for (const line of envTxt.split("\n")) {
  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
}
const { decryptSecret } = require("./lib/crypto-box.ts");

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
const HOST = "51.79.226.200";
const PORT = 22;

function getEnc() {
  const url = process.env.DATABASE_URL;
  const out = execSync(
    `psql "${url}" -tA -c "SELECT \\"rootPasswordEnc\\" FROM \\"Server\\" WHERE id='${SERVER_ID}';"`,
    { encoding: "utf8" }
  ).trim();
  return out;
}

async function main() {
  const b64 = process.argv[2];
  if (!b64) throw new Error("no script arg");
  const script = Buffer.from(b64, "base64").toString("utf8");
  const enc = getEnc();
  const password = decryptSecret(enc);
  if (!password) throw new Error("could not decrypt root password");

  const conn = new Client();
  await new Promise((resolve, reject) => {
    conn
      .on("ready", resolve)
      .on("error", reject)
      .connect({ host: HOST, port: PORT, username: "root", password, readyTimeout: 20000 });
  });
  const res = await new Promise((resolve, reject) => {
    conn.exec(script, (err, stream) => {
      if (err) return reject(err);
      let stdout = "", stderr = "";
      stream
        .on("close", (code) => resolve({ code, stdout, stderr }))
        .on("data", (d) => (stdout += d.toString()))
        .stderr.on("data", (d) => (stderr += d.toString()));
    });
  });
  conn.end();
  process.stdout.write(res.stdout);
  if (res.stderr) process.stderr.write("\n[STDERR]\n" + res.stderr);
  process.stdout.write(`\n[EXIT ${res.code}]\n`);
  process.exit(res.code === 0 ? 0 : 1);
}
main().catch((e) => {
  console.error("RUNNER ERROR:", e.message);
  process.exit(2);
});

